config.script:
if 'type' in event.data.keys():
	typeid=event.data['type']
	uuid=event.data['uuid']
	if typeid != 'Container':
		path=exchange.architecturebuilder.viewCanvas.connectionRules.getComponentPath(typeid, view='Config')
	else:
		path='Exchange/ArchitectureBuilder/Frames/EmbeddedViews/SiteConfig'
	system.perspective.openPopup(uuid, path, {'uuid': uuid}, title=event.data['name'],position={'height':'auto'})
elif 'modules' in event.data.keys():
	uuid=event.data['uuid']
	vendor=event.data['vendor']
	system.perspective.sendMessage('openPopup', {
				'uuid':'modules', 
				'path':'Exchange/ArchitectureBuilder/Modules/ModuleSelection',
				'params':{
					'gatewayUUID':uuid, 'providerFlag':vendor},
				'title':'Module Selection'},scope='session')
